import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"GLM Free API — Single File Bridge","description":"A complete OpenAI- and Anthropic-compatible API for GLM in a single Go file. No browser, no headless Chrome, account pool included.","frontmatter":{"title":"GLM Free API — Single File Bridge","description":"A complete OpenAI- and Anthropic-compatible API for GLM in a single Go file. No browser, no headless Chrome, account pool included."},"headers":[],"relativePath":"en/projects/glm-free-api/index.md","filePath":"en/projects/glm-free-api/index.md"}`),a={name:`en/projects/glm-free-api/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="glm-free-api-—-single-file-bridge" tabindex="-1">GLM Free API — Single File Bridge <a class="header-anchor" href="#glm-free-api-—-single-file-bridge" aria-label="Permalink to “GLM Free API — Single File Bridge”">​</a></h1><p><strong><a href="https://github.com/Godde3s/glm-free-api" target="_blank" rel="noreferrer">GLM Free API</a></strong> is my most-starred repository, and the premise is almost rude in its simplicity: a complete API bridge to GLM in <strong>one Go file</strong>, with <strong>zero browser automation</strong>. No headless Chrome eating RAM, no puppeteer flakiness — just HTTP done properly.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to “The problem it solves”">​</a></h2><p>GLM&#39;s web chat is free but locked to a browser. Existing bridges wrapped that browser in automation, which meant memory blowups, captcha churn and crashes under load. I went the opposite way: reverse-engineered the web session flow, then implemented the protocol natively in Go. The result starts in milliseconds and scales to concurrent requests without a single browser process.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><ul><li><strong>OpenAI-compatible</strong> <code>/v1/chat/completions</code> — drop-in for any existing client.</li><li><strong>Anthropic-compatible</strong> <code>/v1/messages</code> — so Claude-flavored tooling works too.</li><li><strong>Account pool</strong> — rotate multiple sessions, mark dead ones, stay under rate limits.</li><li><strong>Streaming</strong> — real SSE, not fake chunked responses.</li><li><strong>One file</strong> — <code>go build</code>, run, done. Read the whole implementation in one sitting.</li></ul><blockquote><p>One file is not a stunt. It is a statement that infrastructure should be readable — you can audit every line in ten minutes.</p></blockquote><p>The same architecture spawned siblings: <a href="/Usf/en/projects/ghost-brain/">GhostBrain</a> (Gemini), qwen-free-api and deepseek-free-api. Together with <a href="/Usf/en/projects/omnirouter/">OmniRouter</a>, they form a complete free-tier AI infrastructure that costs nothing to run.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};